def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]
    average_value = (v1 + v2 + v3) / 3

    return {
        "value": average_value,
        "trace": {
            "values": [v1, v2, v3],
            "count": 3,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "shares"
            }
        }
    }
